ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                    struct msghdr *msg, size_t size,
                                    int msg_flags) {
    struct sock *sk = sock->sk;
    ssize_t received = 0;
    struct sk_buff *skb;
    int error = 0;

    while (1) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb) {
            if (msg_flags & MSG_DONTWAIT) {
                return -EAGAIN;
            }
            error = wait_for_poll(sk, NULL, iocb->ki_wait, iocb->ki_timeout);
            if (error)
                return error;
            continue;
        }

        if (skb->len > size) {
            msg->msg_flags |= MSG_TRUNC;
        }

        received = skb->len;
        if (msg->msg_flags & MSG_TRUNC) {
            received = size;
        }

        if (copy_to_iter(skb->data, received, msg->msg_iter) != received) {
            kfree_skb(skb);
            return -EFAULT;
        }

        if (skb->pkt_type == PACKET_NOTIFICATION) {
            handle_notification(skb);
        }

        kfree_skb(skb);
        break;
    }

    return received;
}

int receive_and_process_notification(struct kiocb *iocb, struct socket *sock,
                                     struct msghdr *msg, size_t size,
                                     int msg_flags) {
    int ret = 0;
    struct sk_buff *skb;
    struct sock *sk = sock->sk;
    int copied = 0;

    while (1) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb) {
            int len = skb->len;

            if (len > size) {
                len = size;
            }

            if (skb_copy_datagram_msg(skb, 0, msg, 0, len) < 0) {
                ret = -EFAULT;
                break;
            }

            copied += len;
            if (copied >= size) {
                ret = size;
            } else {
                ret = copied;
            }

            kfree_skb(skb);
            break;
        } else if (msg_flags & MSG_DONTWAIT) {
            ret = -EAGAIN;
            break;
        } else {
            schedule();
        }
    }

    return ret;
}

#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/wait.h>
#include <linux/slab.h>
#include <linux/mm.h>

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                    struct msghdr *msg, size_t size,
                                    int msg_flags) {
    struct sock *sk = sock->sk;
    ssize_t res;
    long int timeout;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (msg_flags & MSG_DONTWAIT) {
        if (!sock->sk->sk_data_ready)
            return -EAGAIN;
    }

    timeout = sock_rcvtimeo(sk, msg_flags & MSG_DONTWAIT);

    res = sock_recvmsg(iocb, sock, msg, size, msg_flags);
    if (res < 0)
        return res;

    if (msg->msg_name) {
        struct sockaddr_in *addr = (struct sockaddr_in *)msg->msg_name;
        addr->sin_port = htons(sk->sk_remote_port);
        addr->sin_addr.s_addr = sk->sk_remote_ip;
    }

    return res;
}

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags)
{
    ssize_t ret = 0;
    struct sk_buff *skb = NULL;
    struct sock *sk = sock->sk;

    if (sk == NULL) {
        return -EINVAL;
    }

    skb = skb_recv_datagram(sk, msg_flags, &ret);
    if (!skb) {
        return ret;
    }

    ret = skb->len;
    if (size < ret) {
        ret = -EMSGSIZE;
    }

    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    msg->msg_name = skb->cb;
    msg->msg_namelen = sizeof(struct sockaddr);

    ret = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, ret);
    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    kfree_skb(skb);
    return ret;
}

int receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    struct sock *sk = sock->sk;
    int flags = msg_flags;
    int err, copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    while (1) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb)
            break;

        if (signal_pending(current))
            return -ERESTARTSYS;

        if (!skb_queue_empty(&sk->sk_error_queue)) {
            err = sock_error_recverr(sk);
            if (err)
                return err;
        }

        if (flags & MSG_DONTWAIT)
            return -EAGAIN;

        if (sk->sk_shutdown & RCV_SHUTDOWN)
            return copied ? copied : -ENODATA;

        sk_wait_data(sk, &skb, NULL);
    }

    copied = min(skb->len, size);
    if (copied < skb->len)
        msg->msg_flags |= MSG_TRUNC;

    err = skb_copy_datagram_iovec(skb, 0, msg->msg_iter.iov, copied);
    if (err) {
        kfree_skb(skb);
        return -EFAULT;
    }

    if (skb->pkt_type == PACKET_LOOPBACK)
        msg->msg_name = NULL;
    else {
        msg->msg_namelen = sizeof(struct sockaddr_in);
        memcpy(msg->msg_name, &skb->cb, sizeof(struct sockaddr_in));
    }

    kfree_skb(skb);
    return copied;
}
